libs/talon/deepagents_talon/channels/wha:
"use strict";

const fs = require("fs");
const http = require("http");
const path = require("path");
const { Client, LocalAuth, MessageMedia } = require("whatsapp-web.js");
const qrcode = require("qrcode-terminal");
const {
  AckTracker,
  SentBodyReservations,
  contactIdentityIds,
  createCompatibleClientClass,
  isSelfChat,
  messageSenderId,
  normalizeMessage,
  quotedMessageContext,
  reactionEntry,
  serializedId,
  widString,
} = require("./id_compat");
const { downloadMedia } = require("./media");

const host = process.env.WHATSAPP_BRIDGE_HOST || "127.0.0.1";
const port = Number(process.env.WHATSAPP_BRIDGE_PORT || "3000");
const sessionDir = path.resolve(process.env.WHATSAPP_SESSION_DIR || path.join(process.cwd(), ".whatsapp"));
const mediaDir = path.resolve(process.env.WHATSAPP_MEDIA_DIR || path.join(sessionDir, "..", "media"));
const bridgeToken = process.env.WHATSAPP_BRIDGE_TOKEN || "";
const maxMediaBytes = Number(process.env.WHATSAPP_MAX_MEDIA_BYTES) || 64 * 1024 * 1024;
const webVersionCacheUrl =
  process.env.WHATSAPP_WEB_VERSION_CACHE_URL ||
  "https://raw.githubusercontent.com/wppconnect-team/wa-version/main/html/2.3000.1026029003.html";

const ACK_TIMEOUT_MS = 60 * 1000;
const MAX_CACHED_SENT_MESSAGES = 200;

let status = "disconnected";
let botId = null;
let botIds = [];
let bridgeMediaSends = 0;
const queue = [];
const sentMessageIds = new Set();
const sentMessages = new Map();
const sentBodies = new SentBodyReservations();
const ackTracker = new AckTracker({
  timeoutMs: ACK_TIMEOUT_MS,
  onAck: (ack, tracked) => {
    console.log(`[bridge] Outbound message acknowledgement; ack=${ack} tracked=${tracked}`);
  },
  onTimeout: () => {
    console.error("[bridge] Outbound message acknowledgement timed out");
  },
});

process.on("unhandledRejection", (reason) => {
  const message = reason && reason.message ? reason.message : reason;
  console.error("Unhandled rejection:", message);
});

if (!bridgeToken) {
  console.error("WHATSAPP_BRIDGE_TOKEN is required");
  process.exit(1);
}

fs.mkdirSync(sessionDir, { recursive: true });
fs.mkdirSync(mediaDir, { recursive: true });
cleanStaleLocks(sessionDir);

const chromePath = process.env.CHROME_PATH || process.env.WHATSAPP_CHROME_PATH || findChrome();
if (chromePath) {
  console.log("Using configured Chrome executable");
} else {
  console.log("No system Chrome found; using Puppeteer's bundled browser if available");
}

const puppeteer = {
  headless: true,
  args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-gpu"],
};
if (chromePath) {
  puppeteer.executablePath = chromePath;
}

const CompatibleClient = createCompatibleClientClass(Client);
const client = new CompatibleClient({
  authStrategy: new LocalAuth({
    dataPath: sessionDir,
  }),
  puppeteer,
  webVersionCache: {
    type: "remote",
    remotePath: webVersionCacheUrl,
  },
});

client.on("qr", (qr) => {
  status = "qr_pending";
  console.log("Scan this QR code to pair WhatsApp:");
  qrcode.generate(qr, { small: true });
});

client.on("ready", () => {
  void onClientReady();
});

client.on("disconnected", (reason) => {
  status = "disconnected";
  console.log(`WhatsApp disconnected: ${reason || "unknown reason"}`);
});

client.on("auth_failure", (message) => {
  status = "disconnected";
  console.error(`WhatsApp auth failure: ${message || "unknown error"}`);
});

client.on("compatibility_error", (error) => {
  status = "compatibility_error";
  console.error(`[bridge] WhatsApp compatibility setup failed: ${error.message || error}`);
});

client.on("message_create", (message) => {
  if (message.fromMe === true) {
    void enqueueMessage(message, true);
  }
});

client.on("message", (message) => {
  void enqueueMessage(message, false);
});

client.on("message_reaction", (reaction) => {
  console.log('[bridge] talon_event {"event":"whatsapp.bridge.reaction.received"}');
  try {
    const entry = reactionEntry(reaction, botId, botIds);
    if (entry) {
      queue.push(entry);
      console.log('[bridge] talon_event {"event":"whatsapp.bridge.reaction.queued"}');
    }
  } catch (error) {
    console.log('[bridge] talon_event {"event":"whatsapp.bridge.reaction.parse_failed"}');
    throw error;
  }
});

client.on("media_uploaded", (message) => {
  if (bridgeMediaSends === 0) {
    void enqueueMessage(message, true);
  }
});

client.on("message_ack", (message, ack) => {
  recordMessageAck(message, ack);
});

async function onClientReady() {
  try {
    const compatibility = client.idCompatibility;
    if (!compatibility || compatibility.compatible !== true) {
      throw new Error("WhatsApp message key compatibility is not active");
    }
    const webVersion = safeVersion(await client.getWWebVersion());
    botIds = await resolveBotIds();
    botId = botIds[0] || null;
    status = "connected";
    console.log(
      `[bridge] WhatsApp connected; webVersion=${webVersion} idCompatibilityInstalled=${compatibility.installed === true} botIdAvailable=${Boolean(botId)} botIdAliasAvailable=${botIds.length > 1}`,
    );
  } catch (error) {
    status = "compatibility_error";
    console.error(`[bridge] WhatsApp compatibility setup failed: ${error.message || error}`);
  }
}

async function resolveBotIds() {
  const initialIds = contactIdentityIds(client.info && client.info.wid);
  if (initialIds.length === 0 || typeof client.getContactLidAndPhone !== "function") {
    return initialIds;
  }
  try {
    const mappings = await client.getContactLidAndPhone(initialIds);
    return contactIdentityIds(initialIds[0], mappings);
  } catch (_error) {
    console.log("[bridge] Paired-account ID aliases unavailable; using primary ID only");
    return initialIds;
  }
}

async function enqueueMessage(message, fromSelf) {
  normalizeMessage(message);
  const data = message && message._data ? message._data : {};
  const messageFrom = widString(message.from) || widString(data.from);
  if (messageFrom === "status@broadcast") {
    return;
  }
  if (fromSelf && isBridgeSentMessage(message)) {
    return;
  }

  const messageId = serializedId(message.id) || serializedId(data.id);
  const messageTo = widString(message.to) || widString(data.to);
  const remoteId = widString(message.id && message.id.remote) || widString(data.id && data.id.remote);
  const chatId = (fromSelf ? messageTo : messageFrom) || remoteId;
  if (!messageId || !chatId) {
    console.error("Skipping WhatsApp message without a message id or chat id");
    return;
  }
  const selfChat = isSelfChat(fromSelf, chatId, botIds);
  if (fromSelf && !selfChat) {
    console.log("[bridge] Ignoring paired-account message outside the self-chat");
    return;
  }

  const [chat, contact] = await Promise.all([safeGetChat(message), safeGetContact(message)]);
  const media = await downloadMessageMedia(message);
  const mediaType = classifyMedia(message, media);
  if (message.hasMedia && media.length === 0) {
    console.log(
      `[bridge] Message media unavailable; type=${message.type || "unknown"} mediaType=${mediaType}`,
    );
  }
  const senderId = messageSenderId(message, fromSelf, botId, messageFrom);
  const senderName =
    (contact && (contact.pushname || contact.name || contact.shortName)) ||
    data.notifyName ||
    data.senderName ||
    senderId ||
    null;
  const chatName = (chat && chat.name) || data.chatName || chatId;
  const isGroup =
    chat && typeof chat.isGroup === "boolean" ? chat.isGroup : chatId.endsWith("@g.us");
  const quote = await quotedMessageContext(message);

  const entry = {
    text: message.body || "",
    body: message.body || "",
    message_type: message.type || "chat",
    messageType: message.type || "chat",
    media_type: mediaType,
    mediaType,
    chat_id: chatId,
    chatId,
    chat_id_from: messageFrom,
    chatIdFrom: messageFrom,
    chat_name: chatName,
    chatName,
    chat_type: isGroup ? "group" : "direct",
    chatType: isGroup ? "group" : "direct",
    isGroup,
    user_id: senderId || null,
    senderId: senderId || null,
    user_name: senderName,
    senderName,
    message_id: messageId,
    messageId,
    has_media: Boolean(message.hasMedia || media.length > 0),
    hasMedia: Boolean(message.hasMedia || media.length > 0),
    media_paths: media.map((item) => item.path),
    mediaPaths: media.map((item) => item.path),
    media_urls: media.map((item) => item.path),
    mediaUrls: media.map((item) => item.path),
    media_mime_types: media.map((item) => item.mimeType),
    mediaMimeTypes: media.map((item) => item.mimeType),
    media_types: media.map((item) => item.mimeType),
    mediaTypes: media.map((item) => item.mimeType),
    media_file_names: media.map((item) => item.fileName),
    from_self: fromSelf,
    fromSelf,
    self_chat: selfChat,
    selfChat,
    mentionedIds: normalizeIds(message.mentionedIds || []),
    botIds,
    quoted_participant: quote.participant,
    quotedParticipant: quote.participant,
    quoted_message_id: quote.messageId,
    quotedMessageId: quote.messageId,
    reply_context_status: quote.status,
    replyContextStatus: quote.status,
    raw_message: {
      from: messageFrom,
      to: messageTo,
      author: widString(message.author),
      fromMe: message.fromMe === true,
      idFromMe: message.id && message.id.fromMe === true,
      timestamp: message.timestamp || null,
    },
  };

  console.log(
    `[bridge] Queued message; fromSelf=${fromSelf} hasMedia=${entry.hasMedia} chatType=${entry.chatType}`,
  );
  queue.push(entry);
}

function cleanStaleLocks(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (_error) {
    return;
  }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      cleanStaleLocks(full);
      continue;
    }
    if (/^Singleton(Lock|Socket|Cookie)$/.test(entry.name)) {
      try {
        fs.unlinkSync(full);
      } catch (_error) {
        // Best effort cleanup only.
      }
    }
  }
}

function findChrome() {
  const candidates =
    process.platform === "darwin"
      ? [
          "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
          "/Applications/Chromium.app/Contents/MacOS/Chromium",
          "/Applications/Google Chrome Canary.app/Contents/MacOS/Google Chrome Canary",
        ]
      : process.platform === "win32"
        ? [
            process.env.PROGRAMFILES
              ? path.join(process.env.PROGRAMFILES, "Google", "Chrome", "Application", "chrome.exe")
              : null,
            process.env["PROGRAMFILES(X86)"]
              ? path.join(
                  process.env["PROGRAMFILES(X86)"],
                  "Google",
                  "Chrome",
                  "Application",
                  "chrome.exe",
                )
              : null,
          ]
        : [
            "/usr/bin/google-chrome",
            "/usr/bin/google-chrome-stable",
            "/usr/bin/chromium",
            "/usr/bin/chromium-browser",
            "/snap/bin/chromium",
          ];

  for (const candidate of candidates) {
    if (candidate && fs.existsSync(candidate)) {
      return candidate;
    }
  }
  return undefined;
}

async function safeGetChat(message) {
  try {
    return await message.getChat();
  } catch (_error) {
    console.log("[bridge] getChat failed (non-fatal)");
    return null;
  }
}

async function safeGetContact(message) {
  try {
    return await message.getContact();
  } catch (_error) {
    console.log("[bridge] getContact failed (non-fatal)");
    return null;
  }
}

async function downloadMessageMedia(message) {
  if (!message.hasMedia) {
    return [];
  }
  try {
    const messageId = serializedId(message.id) || String(Date.now());
    const expectedSize = messageMediaSize(message);
    if (expectedSize !== null && expectedSize > maxMediaBytes) {
      console.log(
        `[bridge] Skipping oversized media; bytes=${expectedSize} maxBytes=${maxMediaBytes}`,
      );
      return [];
    }
    const media = await downloadMedia(client.pupPage, message);
    if (!media || !media.data) {
      return [];
    }
    const extension = mediaExtension(media.mimetype, message.type);
    const fileName = `${Date.now()}_${messageId.replace(/[^A-Za-z0-9]/g, "_")}.${extension}`;
    const filePath = path.join(mediaDir, fileName);
    const size = decodedBase64Size(media.data);
    if (size > maxMediaBytes) {
      console.log(
        `[bridge] Skipping oversized media; bytes=${size} maxBytes=${maxMediaBytes}`,
      );
      return [];
    }
    fs.writeFileSync(filePath, Buffer.from(media.data, "base64"), { mode: 0o600 });
    return [
      {
        path: filePath,
        mimeType: media.mimetype || "application/octet-stream",
        fileName: media.filename || fileName,
      },
    ];
  } catch (error) {
    console.error("Media download failed:", error.message || error);
    return [];
  }
}

function classifyMedia(message, media) {
  const rawType = String(message.type || "").toLowerCase();
  const mimeType = messageMimeType(message, media);
  if (rawType === "ptt" || rawType === "audio" || mimeType.startsWith("audio/")) {
    return "voice";
  }
  if (rawType === "image" || rawType === "sticker" || mimeType.startsWith("image/")) {
    return "image";
  }
  if (rawType === "video" || mimeType.startsWith("video/")) {
    return "video";
  }
  if (message.hasMedia) {
    return "document";
  }
  return "text";
}

function messageMimeType(message, media) {
  if (media.length > 0) {
    return String(media[0].mimeType || "").toLowerCase();
  }
  const data = message && message._data ? message._data : {};
  return String(message.mimetype || data.mimetype || data.mimetypeOverride || "").toLowerCase();
}

function messageMediaSize(message) {
  const data = message && message._data ? message._data : {};
  const candidates = [data.size, data.fileSize];
  for (const candidate of candidates) {
    const parsed = Number(candidate);
    if (Number.isFinite(parsed) && parsed >= 0) {
      return parsed;
    }
  }
  return null;
}

function mediaExtension(mimeType, messageType) {
  const raw = String(mimeType || "").split(";", 1)[0];
  const subtype = raw.includes("/") ? raw.split("/")[1] : "";
  const cleaned = subtype.replace(/[^A-Za-z0-9]/g, "");
  if (cleaned) {
    return cleaned === "plain" ? "txt" : cleaned;
  }
  if (messageType === "ptt" || messageType === "audio") {
    return "ogg";
  }
  return "bin";
}

function decodedBase64Size(value) {
  const data = String(value || "");
  const padding = data.endsWith("==") ? 2 : data.endsWith("=") ? 1 : 0;
  return Math.floor((data.length * 3) / 4) - padding;
}

function normalizeIds(values) {
  return values.map(widString).filter(Boolean);
}

function safeVersion(value) {
  const version = String(value || "unknown").replace(/[^0-9A-Za-z._-]/g, "");
  return version.slice(0, 64) || "unknown";
}

function cacheSentMessage(message) {
  normalizeMessage(message);
  const id = serializedId(message && message.id);
  if (!id) {
    return null;
  }
  sentMessageIds.add(id);
  sentMessages.set(id, message);
  if (sentMessages.size > MAX_CACHED_SENT_MESSAGES) {
    const oldest = sentMessages.keys().next().value;
    sentMessages.delete(oldest);
    sentMessageIds.delete(oldest);
    ackTracker.forget(oldest);
  }
  return id;
}

function rememberSentMessage(message) {
  const id = cacheSentMessage(message);
  if (!id) {
    return null;
  }
  ackTracker.register(id, message.ack);
  return id;
}

function recordMessageAck(message, ack) {
  normalizeMessage(message);
  ackTracker.record(serializedId(message && message.id), ack);
}

function isBridgeSentMessage(message) {
  const id = serializedId(message.id);
  if (id && sentMessageIds.has(id)) {
    return true;
  }
  return sentBodies.has(message.body || "");
}

async function withSentBodyReservation(body, operation) {
  const release = sentBodies.reserve(body);
  try {
    return await operation();
  } finally {
    release();
  }
}

async function withBridgeMediaSend(operation) {
  bridgeMediaSends += 1;
  try {
    return await operation();
  } finally {
    bridgeMediaSends -= 1;
  }
}

function readJson(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => {
      if (chunks.length === 0) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString("utf8")));
      } catch (error) {
        reject(error);
      }
    });
    req.on("error", reject);
  });
}

function sendJson(res, code, body) {
  const data = Buffer.from(JSON.stringify(body));
  res.writeHead(code, {
    "content-type": "application/json",
    "content-length": String(data.length),
  });
  res.end(data);
}

function isAuthorized(req) {
  return req.headers.authorization === `Bearer ${bridgeToken}`;
}

function containedMediaPath(value) {
  if (typeof value !== "string" || !value) {
    return null;
  }
  const resolved = path.resolve(value);
  const root = path.resolve(mediaDir);
  if (resolved === root || !resolved.startsWith(root + path.sep)) {
    return null;
  }
  return resolved;
}

async function handle(req, res) {
  try {
    if (!isAuthorized(req)) {
      sendJson(res, 401, { success: false, error: "unauthorized" });
      return;
    }

    if (req.method === "GET" && req.url === "/health") {
      sendJson(res, 200, { status, botId });
      return;
    }

    if (req.method === "GET" && req.url === "/messages") {
      sendJson(res, 200, queue.splice(0, queue.length));
      return;
    }

    if (req.method === "POST" && status !== "connected") {
      sendJson(res, 503, { success: false, error: "WhatsApp bridge is not connected" });
      return;
    }

    if (req.method === "POST" && req.url === "/send") {
      const body = await readJson(req);
      const chatId = body.chat_id || body.chatId;
      const text = body.text || body.message || "";
      if (!chatId || !text) {
        sendJson(res, 400, { success: false, error: "chat_id and text required" });
        return;
      }
      const messageId = await withSentBodyReservation(text, async () => {
        const sent = await client.sendMessage(chatId, text, {
          quotedMessageId: body.replyTo || body.reply_to || undefined,
        });
        return rememberSentMessage(sent);
      });
      if (!messageId) {
        sendJson(res, 502, { success: false, error: "WhatsApp send returned no message id" });
        return;
      }
      sendJson(res, 200, {
        success: true,
        message_id: messageId,
        messageId,
      });
      return;
    }

    if (req.method === "POST" && req.url === "/send-media") {
      const body = await readJson(req);
      const chatId = body.chat_id || body.chatId;
      const filePath = body.path || body.filePath;
      if (!chatId || !filePath) {
        sendJson(res, 400, { success: false, error: "chat_id and path required" });
        return;
      }
      const safePath = containedMediaPath(filePath);
      if (!safePath) {
        sendJson(res, 400, { success: false, error: "media path is not allowed" });
        return;
      }
      const media = MessageMedia.fromFilePath(safePath);
      if (body.fileName || body.file_name) {
        media.filename = body.fileName || body.file_name;
      }
      const caption = body.caption || undefined;
      const messageId = await withBridgeMediaSend(() =>
        withSentBodyReservation(caption, async () => {
          const sent = await client.sendMessage(chatId, media, {
            caption,
            sendMediaAsDocument: body.mediaType === "document",
          });
          return rememberSentMessage(sent);
        }),
      );
      if (!messageId) {
        sendJson(res, 502, { success: false, error: "WhatsApp send returned no message id" });
        return;
      }
      sendJson(res, 200, {
        success: true,
        message_id: messageId,
        messageId,
      });
      return;
    }

    if (req.method === "POST" && req.url === "/typing") {
      const body = await readJson(req);
      const chatId = body.chat_id || body.chatId;
      if (!chatId) {
        sendJson(res, 400, { success: false, error: "chat_id required" });
        return;
      }
      const chat = await client.getChatById(chatId);
      await chat.sendStateTyping();
      sendJson(res, 200, { success: true, ok: true });
      return;
    }

    if (req.method === "POST" && req.url === "/edit") {
      const body = await readJson(req);
      const messageId = body.message_id || body.messageId;
      const content = body.content || body.message || "";
      if (!messageId || !content) {
        sendJson(res, 400, { success: false, error: "message_id and content required" });
        return;
      }
      const message = sentMessages.get(messageId) || (await client.getMessageById(messageId));
      if (!message) {
        sendJson(res, 200, { success: false, error: "message not found" });
        return;
      }
      normalizeMessage(message);
      const edited = await withSentBodyReservation(content, () => message.edit(content));
      if (!edited) {
        sendJson(res, 200, { success: false, error: "message could not be edited" });
        return;
      }
      const editedId = cacheSentMessage(edited) || messageId;
      sendJson(res, 200, {
        success: true,
        message_id: editedId,
        messageId: editedId,
      });
      return;
    }

    sendJson(res, 404, { success: false, error: "not found" });
  } catch (error) {
    sendJson(res, 500, { success: false, error: error.message || String(error) });
  }
}

const server = http.createServer((req, res) => {
  void handle(req, res);
});

server.listen(port, host, () => {
  console.log(`WhatsApp bridge listening on http://${host}:${port}`);
});

client.initialize();

process.on("SIGTERM", async () => {
  server.close();
  try {
    await client.destroy();
  } catch (_error) {
    // The process is already exiting.
  }
  process.exit(0);
});

"use strict";

function widString(value) {
  if (!value) {
    return null;
  }
  if (typeof value === "string") {
    return value;
  }
  if (typeof value !== "object") {
    return null;
  }
  if (typeof value._serialized === "string" && value._serialized) {
    return value._serialized;
  }
  if (typeof value.$1 === "string" && value.$1) {
    return value.$1;
  }
  if (typeof value.user === "string" && typeof value.server === "string") {
    return `${value.user}@${value.server}`;
  }
  return null;
}

function contactIdentityIds(primary, mappings = []) {
  const aliases = mappings.flatMap((mapping) => [mapping && mapping.lid, mapping && mapping.pn]);
  return [...new Set([primary, ...aliases].map(widString).filter(Boolean))];
}

function isSelfChat(fromSelf, chatId, ownIds) {
  if (fromSelf !== true) {
    return false;
  }
  const serializedChatId = widString(chatId);
  return Boolean(serializedChatId && ownIds.some((value) => widString(value) === serializedChatId));
}

function serializedId(value) {
  const serialized = widString(value);
  if (serialized || !value || typeof value !== "object") {
    return serialized;
  }
  const remote = widString(value.remote);
  if (remote && typeof value.id === "string" && value.id) {
    return `${value.fromMe === true ? "true" : "false"}_${remote}_${value.id}`;
  }
  return typeof value.id === "string" && value.id ? value.id : null;
}

function messageSenderId(message, fromSelf, botId, messageFrom) {
  return fromSelf === true && botId ? botId : widString(message.author) || messageFrom;
}

function reactionEntry(reaction, botId, botIds) {
  const messageId = serializedId(reaction.msgId);
  const chatId = widString(reaction.msgId && reaction.msgId.remote);
  const fromSelf = Boolean(reaction.id && reaction.id.fromMe === true);
  const selfChat = isSelfChat(fromSelf, chatId, botIds);
  const senderId = fromSelf ? botId : widString(reaction.senderId);
  const reason = !messageId ? "missing_message_id"
    : !chatId ? "missing_chat_id"
    : !senderId ? "missing_sender_id"
    : !reaction.reaction ? "missing_emoji"
    : chatId === "status@broadcast" ? "status_broadcast"
    : fromSelf && !selfChat ? "self_outside_self_chat" : null;
  console.log(`[bridge] talon_event ${JSON.stringify({
    event: reason ? "whatsapp.bridge.reaction.rejected" : "whatsapp.bridge.reaction.converted",
    reason, from_self: fromSelf, self_chat: selfChat,
    message_id_present: Boolean(messageId), chat_id_present: Boolean(chatId),
    sender_id_present: Boolean(senderId), emoji_present: Boolean(reaction.reaction),
    bot_id_present: Boolean(botId), bot_alias_count: botIds.length,
  })}`);
  if (reason) {
    return null;
  }
  return {
    event_type: "reaction", chat_id: chatId, user_id: senderId,
    message_id: messageId, text: reaction.reaction,
    from_self: fromSelf, self_chat: selfChat,
  };
}

async function quotedMessageContext(message) {
  if (!message.hasQuotedMsg) {
    return { participant: null, messageId: null, status: "not_reply" };
  }
  try {
    const quoted = await message.getQuotedMessage();
    return {
      participant: widString(quoted.author) || widString(quoted.from),
      messageId: serializedId(quoted.id),
      status: "resolved",
    };
  } catch (_error) {
    return { participant: null, messageId: null, status: "lookup_failed" };
  }
}

function normalizeId(value) {
  if (!value || typeof value !== "object" || value._serialized) {
    return value;
  }
  const serialized = serializedId(value);
  if (!serialized) {
    return value;
  }
  try {
    value._serialized = serialized;
    if (value._serialized === serialized) {
      return value;
    }
  } catch (_error) {
    return { ...value, _serialized: serialized };
  }
  return { ...value, _serialized: serialized };
}

function normalizeMessage(message) {
  if (!message || typeof message !== "object") {
    return message;
  }
  const data = message._data && typeof message._data === "object" ? message._data : {};
  message.id = normalizeId(message.id || data.id);
  message._data = { ...data, id: normalizeId(data.id || message.id) };
  message.from = widString(message.from) || widString(data.from);
  message.to = widString(message.to) || widString(data.to);
  message.author = widString(message.author) || widString(data.author);
  return message;
}

function installMessageKeyCompatibility() {
  const MessageKey = window.require("WAWebMsgKey");
  if (!MessageKey || !MessageKey.prototype) {
    return { installed: false, compatible: false };
  }
  const prototype = MessageKey.prototype;
  let descriptorOwner = prototype;
  let descriptor;
  while (descriptorOwner && !descriptor) {
    descriptor = Object.getOwnPropertyDescriptor(descriptorOwner, "_serialized");
    descriptorOwner = Object.getPrototypeOf(descriptorOwner);
  }
  let installed = false;
  if (!descriptor) {
    Object.defineProperty(prototype, "_serialized", {
      configurable: true,
      get() {
        if (typeof this.$1 === "string" && this.$1) {
          return this.$1;
        }
        const remote =
          typeof this.remote === "string"
            ? this.remote
            : this.remote &&
                (this.remote._serialized ||
                  this.remote.$1 ||
                  (this.remote.user && this.remote.server
                    ? `${this.remote.user}@${this.remote.server}`
                    : null));
        if (!remote || typeof this.id !== "string" || !this.id) {
          return undefined;
        }
        return `${this.fromMe === true ? "true" : "false"}_${remote}_${this.id}`;
      },
    });
    installed = true;
  }
  const chats = window.require("WAWebCollections").Chat.getModelsArray();
  const sample = chats.map((chat) => chat.lastReceivedKey).find(Boolean);
  const compatible = !sample || typeof sample._serialized === "string";
  return { installed, compatible };
}

async function installPageCompatibility(page) {
  const result = await page.evaluate(installMessageKeyCompatibility);
  if (!result || result.compatible !== true) {
    throw new Error("WhatsApp message key compatibility check failed");
  }
  return result;
}

function createCompatibleClientClass(ClientClass) {
  return class CompatibleClient extends ClientClass {
    async attachEventListeners() {
      try {
        this.idCompatibility = await installPageCompatibility(this.pupPage);
      } catch (error) {
        this.emit("compatibility_error", error);
        throw error;
      }
      return super.attachEventListeners();
    }
  };
}

function isTerminalAck(ack) {
  return Number.isFinite(ack) && (ack < 0 || ack >= 1);
}

class AckTracker {
  constructor({ timeoutMs, onAck, onTimeout, maxEarlyAcks = 200 }) {
    this.timeoutMs = timeoutMs;
    this.onAck = onAck;
    this.onTimeout = onTimeout;
    this.maxEarlyAcks = maxEarlyAcks;
    this.known = new Set();
    this.pending = new Map();
    this.early = new Map();
  }

  register(id, currentAck) {
    this.known.add(id);
    const pendingTimer = this.pending.get(id);
    if (pendingTimer) {
      clearTimeout(pendingTimer);
      this.pending.delete(id);
    }
    const earlyAck = this.early.get(id);
    this.early.delete(id);
    const ack = isTerminalAck(Number(currentAck)) ? Number(currentAck) : earlyAck;
    if (isTerminalAck(ack)) {
      this.onAck(ack, true);
      return;
    }
    const timer = setTimeout(() => {
      this.pending.delete(id);
      this.onTimeout();
    }, this.timeoutMs);
    timer.unref();
    this.pending.set(id, timer);
  }

  record(id, value) {
    const ack = Number(value);
    if (!id || !Number.isFinite(ack)) {
      return false;
    }
    if (!this.known.has(id)) {
      if (isTerminalAck(ack)) {
        this.rememberEarly(id, ack);
      }
      return false;
    }
    const timer = this.pending.get(id);
    if (timer && isTerminalAck(ack)) {
      clearTimeout(timer);
      this.pending.delete(id);
    }
    this.onAck(ack, Boolean(timer));
    return true;
  }

  forget(id) {
    this.known.delete(id);
    const timer = this.pending.get(id);
    if (timer) {
      clearTimeout(timer);
      this.pending.delete(id);
    }
    this.early.delete(id);
  }

  rememberEarly(id, ack) {
    this.early.set(id, ack);
    while (this.early.size > this.maxEarlyAcks) {
      this.early.delete(this.early.keys().next().value);
    }
  }
}

class SentBodyReservations {
  constructor() {
    this.counts = new Map();
  }

  reserve(body) {
    if (!body) {
      return () => {};
    }
    const key = String(body);
    this.counts.set(key, (this.counts.get(key) || 0) + 1);
    return () => this.release(key);
  }

  has(body) {
    return Boolean(body && this.counts.has(String(body)));
  }

  release(key) {
    const count = this.counts.get(key) || 0;
    if (count <= 1) {
      this.counts.delete(key);
    } else {
      this.counts.set(key, count - 1);
    }
  }
}

module.exports = {
  AckTracker,
  SentBodyReservations,
  contactIdentityIds,
  createCompatibleClientClass,
  installMessageKeyCompatibility,
  installPageCompatibility,
  isSelfChat,
  messageSenderId,
  normalizeId,
  normalizeMessage,
  quotedMessageContext,
  reactionEntry,
  serializedId,
  widString,
};

"use strict";

async function downloadMedia(page, message) {
  if (!message.hasMedia) {
    return undefined;
  }
  const media = await page.evaluate(downloadBrowserMedia, message.id._serialized);
  return media || undefined;
}

async function downloadBrowserMedia(messageId) {
  const messages = window.require("WAWebCollections").Msg;
  const message =
    messages.get(messageId) ||
    (await messages.getMessagesById([messageId]))?.messages?.[0];
  if (!message || !message.mediaData || message.mediaData.mediaStage === "REUPLOADING") {
    return null;
  }
  if (message.mediaData.mediaStage !== "RESOLVED") {
    await message.downloadMedia({ downloadEvenIfExpensive: true, rmrReason: 1 });
  }
  if (
    message.mediaData.mediaStage.includes("ERROR") ||
    message.mediaData.mediaStage === "FETCHING"
  ) {
    return undefined;
  }
  try {
    const downloadQpl = {
      addAnnotations() {
        return this;
      },
      addPoint() {
        return this;
      },
    };
    const decrypted = await window.require("WAWebDownloadManager")
      .downloadManager.downloadAndMaybeDecrypt({
        directPath: message.directPath,
        encFilehash: message.encFilehash,
        filehash: message.filehash,
        mediaKey: message.mediaKey,
        mediaKeyTimestamp: message.mediaKeyTimestamp,
        type: message.type,
        mimetype: message.mimetype,
        signal: new AbortController().signal,
        downloadQpl,
      });
    return {
      data: await window.WWebJS.arrayBufferToBase64Async(decrypted),
      mimetype: message.mimetype,
      filename: message.filename,
      filesize: message.size,
    };
  } catch (error) {
    if (error.status === 404) {
      return undefined;
    }
    throw error;
  }
}

module.exports = { downloadMedia };

libs/talon/deepagents_talon/config.py:
"""Configuration loading for the Talon runtime host.

Talon is an experimental runtime and is subject to change or removal at any time.
Set `DEEPAGENTS_TALON_VERBOSITY` per assistant process: 1 (the default) disables
interim chat updates, 2 permits at most two for long tasks, and 3 allows unrestricted
updates. Final replies and host-visible tool activity are unaffected.
"""

from __future__ import annotations

import os
import re
import tempfile
from contextlib import suppress
from dataclasses import dataclass, field
from pathlib import Path
from typing import TYPE_CHECKING
from urllib.parse import urlsplit

if TYPE_CHECKING:
    from collections.abc import Mapping

    from deepagents_talon.history_profiles import EmbeddingProfile
    from deepagents_talon.sandbox import SandboxSettings

_ASSISTANT_ID_PATTERN = re.compile(r"[A-Za-z0-9_.-]{1,128}")
_ENV_PREFIX = "DEEPAGENTS_TALON_"
_RUNTIME_ENV_PREFIXES = (_ENV_PREFIX, "AGENT_", "LANGSMITH_", "OPENAI_", "SPEECH_", "TELEGRAM_")
_RUNTIME_ENV_KEYS = frozenset(
    {
        "BUILTIN_MCP_URL",
        "HOST_LANGCHAIN_API_URL",
        "TELEGRAM_BOT_TOKEN",
        "VOYAGE_API_KEY",
        "OPENROUTER_API_KEY",
    }
)


class TalonConfigError(ValueError):
    """Raised when Talon runtime configuration is invalid."""


@dataclass(frozen=True, slots=True)
class TalonConfig:
    """Runtime configuration for a single Talon assistant process.

    Args:
        assistant_id: Stable identifier used to namespace all local assistant state.
        home: Per-assistant home directory for state, manifests, sessions, and jobs.
        model: Chat model identifier supplied by the operator environment.
        env: Environment values visible to channels, providers, and future adapters.
    """

    assistant_id: str
    home: Path
    model: str | None = None
    env: Mapping[str, str] = field(default_factory=dict, repr=False)

    @classmethod
    def from_env(
        cls,
        env: Mapping[str, str] | None = None,
        *,
        base_home: Path | None = None,
    ) -> TalonConfig:
        """Build runtime configuration from environment variables.

        Args:
            env: Environment mapping to read. Defaults to `os.environ`.
            base_home: Optional base directory for assistant state. Tests and
                embedding hosts can supply this to avoid the user home directory.

        Returns:
            Runtime configuration with a validated assistant id and namespaced home.

        Raises:
            TalonConfigError: If the assistant id, verbosity, or history connection URI is invalid.
        """
        values = os.environ if env is None else env
        assistant_id = _first_present(
            values,
            "DEEPAGENTS_TALON_ASSISTANT_ID",
            "AGENT_ASSISTANT_ID",
            default="default",
        )
        if assistant_id is None:
            msg = "assistant id is required"
            raise TalonConfigError(msg)
        _validate_assistant_id(assistant_id)
        _validate_history_uri(values.get("DEEPAGENTS_TALON_HISTORY_URI"))

        if base_home is None:
            configured_home = values.get("DEEPAGENTS_TALON_HOME")
            root = Path(configured_home) if configured_home else Path.home() / ".deepagents"
        else:
            root = base_home

        model = _first_present(values, "DEEPAGENTS_TALON_MODEL", "AGENT_MODEL", default=None)
        config = cls(
            assistant_id=assistant_id,
            home=root.expanduser() / assistant_id,
            model=model,
            env={key: value for key, value in values.items() if _is_runtime_env(key)},
        )

        _ = config.verbosity
        _ = config.history_reindex
        _ = config.history_vector_search
        _ = config.history_embedding_profile
        return config

    def ensure_home(self) -> Path:
        """Create the per-assistant home directory with restrictive permissions.

        Returns:
            The created per-assistant home directory.
        """
        if not self.home.exists():
            _create_home(self.home)
        self.home.mkdir(mode=0o700, parents=True, exist_ok=True)
        self.home.chmod(0o700)
        _install_defaults(self.home)
        from deepagents_talon.tool_approvals import ToolApprovalStore  # noqa: PLC0415

        ToolApprovalStore(self.home / "tools.json").ensure()
        for child in (
            self.manifest_dir,
            self.agents_dir,
            self.cron_dir,
            self.channel_dir,
            self.inbound_media_dir,
        ):
            child.mkdir(mode=0o700, parents=True, exist_ok=True)
            child.chmod(0o700)
        return self.home

    @property
    def verbosity(self) -> int:
        """Interim updates: 1 disables them, 2 allows at most two, 3 is unrestricted."""
        value = self.env.get("DEEPAGENTS_TALON_VERBOSITY", "1")
        if value not in {"1", "2", "3"}:
            msg = "DEEPAGENTS_TALON_VERBOSITY must be 1, 2, or 3"
            raise TalonConfigError(msg)
        return int(value)

    @property
    def huggingface_cache_dir(self) -> Path:
        """Hugging Face model cache shared across assistants."""
        return self.home.parent / "cache" / "models" / "huggingface"

    @property
    def manifest_dir(self) -> Path:
        """Directory where agent manifest files are materialized."""
        return self.home

    @property
    def agents_dir(self) -> Path:
        """Directory reserved for custom subagent definitions."""
        return self.home / "agents"

    @property
    def cron_dir(self) -> Path:
        """Directory reserved for scheduler state."""
        return self.home / "cron"

    @property
    def channel_dir(self) -> Path:
        """Directory reserved for channel session state."""
        return self.home / "channels"

    @property
    def sandbox(self) -> SandboxSettings | None:
        """Remote sandbox for agent tools, or None to run them on the host."""
        from deepagents_talon.sandbox import SandboxSettings  # noqa: PLC0415

        provider = _env_value(self.env, "DEEPAGENTS_TALON_SANDBOX")
        if provider is None:
            return None
        sandbox_id = _env_value(self.env, "DEEPAGENTS_TALON_SANDBOX_ID")
        return SandboxSettings(
            provider=provider,
            sandbox_id=sandbox_id,
            snapshot=_env_value(self.env, "DEEPAGENTS_TALON_SANDBOX_SNAPSHOT"),
            default_snapshot=self._default_snapshot(provider, sandbox_id),
            setup_script=_env_value(self.env, "DEEPAGENTS_TALON_SANDBOX_SETUP"),
        )

    def _default_snapshot(self, provider: str, sandbox_id: str | None) -> str | None:
        # LangSmith snapshot names are shared across a workspace, so the
        # provider's `deepagents-code` default can belong to another user.
        if provider != "langsmith" or sandbox_id is not None:
            return None
        return f"talon-{self.assistant_id}"

    @property
    def history_uri(self) -> str | None:
        """History URI, or None for the default local SQLite archive."""
        uri = self.env.get("DEEPAGENTS_TALON_HISTORY_URI")
        _validate_history_uri(uri)
        return uri

    @property
    def checkpoint_uri(self) -> str | None:
        """Checkpoint backend URI, independent of the conversation history backend."""
        return _env_value(self.env, "DEEPAGENTS_TALON_CHECKPOINT_URI")

    @property
    def checkpoint_path(self) -> Path:
        """SQLite database used for persistent LangGraph checkpoints."""
        return self._state_path("checkpoints.sqlite", "checkpoint database")

    @property
    def history_vector_search(self) -> bool:
        """Whether optional semantic history indexing is enabled."""
        value = self.env.get("DEEPAGENTS_TALON_HISTORY_VECTOR_SEARCH", "false").strip().lower()
        if value not in {"", "0", "false", "no", "off", "1", "true", "yes", "on"}:
            msg = "DEEPAGENTS_TALON_HISTORY_VECTOR_SEARCH must be a boolean"
            raise TalonConfigError(msg)
        return value in {"1", "true", "yes", "on"}

    @property
    def history_reindex(self) -> bool:
        """Explicitly rebuild an incompatible vector index while retaining transcripts."""
        value = self.env.get("DEEPAGENTS_TALON_HISTORY_REINDEX", "0")
        if value not in {"0", "1"}:
            msg = "DEEPAGENTS_TALON_HISTORY_REINDEX must be 0 or 1"
            raise TalonConfigError(msg)
        return value == "1"

    @property
    def history_embedding_profile(self) -> EmbeddingProfile:
        """Validated embedding settings without importing optional provider packages."""
        from deepagents_talon.history_profiles import parse_profile  # noqa: PLC0415

        return parse_profile(self.env)

    @property
    def history_vector_path(self) -> Path:
        """Separate SQLite database so embedding cannot block checkpoint writes."""
        return self.history_generation_path("")

    def history_generation_path(self, generation: str) -> Path:
        """Resolve a vector generation within the assistant home.

        Args:
            generation: Validated profile fingerprint, or empty for the legacy index.
        """
        if generation and re.fullmatch(r"[a-f0-9]{64}", generation) is None:
            msg = "Invalid history vector generation"
            raise TalonConfigError(msg)
        suffix = f"-{generation}" if generation else ""
        return self._state_path(f"history-vectors{suffix}.sqlite", "history vector database")

    @property
    def conversation_state_path(self) -> Path:
        """JSON file used for active conversation generations."""
        return self._state_path("conversations.json", "conversation state")

    @property
    def model_state_path(self) -> Path:
        """JSON file holding the assistant-wide `/model` selection."""
        return self._state_path("models.json", "model selection state")

    @property
    def effort_state_path(self) -> Path:
        """JSON file holding reasoning effort overrides by model."""
        return self._state_path("effort.json", "reasoning effort state")

    @property
    def smart_model_state_path(self) -> Path:
        """JSON file holding the assistant's `/smart-model` override."""
        return self._state_path("smart-model.json", "smart model selection state")

    def _state_path(self, name: str, description: str) -> Path:
        home = self.home.resolve()
        expected_home = self.home.parent.resolve() / self.home.name
        state_path = (home / name).resolve()
        if home != expected_home or state_path.parent != home:
            msg = f"{description} must remain inside the assistant home"
            raise TalonConfigError(msg)
        return state_path

    @property
    def inbound_media_dir(self) -> Path:
        """Directory reserved for downloaded inbound channel media."""
        return self.home / "media" / "inbound"


def _create_home(home: Path) -> None:
    home.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=".talon-", dir=home.parent) as directory:
        staged = Path(directory) / "home"
        staged.mkdir(mode=0o700)
        _install_defaults(staged)
        try:
            staged.rename(home)
        except OSError:
            if not home.is_dir():
                raise


def _install_defaults(home: Path) -> None:
    defaults = Path(__file__).with_name("defaults")
    for source in defaults.rglob("*.md"):
        contents = source.read_text(encoding="utf-8")
        target = home / source.relative_to(defaults)
        target.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        _publish_default(target, contents)


def _publish_default(target: Path, contents: str) -> None:
    with tempfile.TemporaryDirectory(prefix=".talon-", dir=target.parent) as directory:
        staged = Path(directory) / target.name
        staged.write_text(contents, encoding="utf-8")
        staged.chmod(0o600)
        with suppress(FileExistsError):
            os.link(staged, target)


def _first_present(
    env: Mapping[str, str],
    *keys: str,
    default: str | None,
) -> str | None:
    for key in keys:
        if key in env:
            return env[key]
    return default


def _env_value(env: Mapping[str, str], key: str) -> str | None:
    value = env.get(key, "").strip()
    return value or None


def _validate_assistant_id(assistant_id: str | None) -> None:
    if (
        not assistant_id
        or assistant_id in {".", ".."}
        or not _ASSISTANT_ID_PATTERN.fullmatch(assistant_id)
    ):
        msg = (
            "assistant id must be 1-128 characters and contain only letters, numbers, "
            "underscore, hyphen, or dot"
        )
        raise TalonConfigError(msg)


def _is_runtime_env(key: str) -> bool:
    return key in _RUNTIME_ENV_KEYS or key.startswith(_RUNTIME_ENV_PREFIXES)


def _validate_history_uri(uri: str | None) -> None:
    if uri is None:
        return
    try:
        parsed = urlsplit(uri)
        if parsed.scheme and not parsed.fragment and not any(char.isspace() for char in uri):
            return
    except ValueError:
        pass
    msg = (
        "DEEPAGENTS_TALON_HISTORY_URI must be a URI with a scheme and no whitespace "
        "or fragment; unset it to use the default SQLite archive"
    )
    raise TalonConfigError(msg)

libs/talon/deepagents_talon/data_lifecyc:
"""Sensitive local-state retention and cleanup helpers.

Talon is an experimental runtime and is subject to change or removal at any time.
"""

from __future__ import annotations

import logging
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from pathlib import Path

    from deepagents_talon.config import TalonConfig
    from deepagents_talon.cron import CronJob, CronJobStore

DEFAULT_CRON_JOB_RETENTION_DAYS = 30
DEFAULT_INBOUND_MEDIA_RETENTION_HOURS = 24

logger = logging.getLogger(__name__)


@dataclass(frozen=True, slots=True)
class DataLifecycleReport:
    """Summary of sensitive local-state cleanup.

    Args:
        removed_cron_jobs: Completed cron records deleted from disk.
        removed_media_files: Downloaded inbound media files deleted from disk.
    """

    removed_cron_jobs: tuple[CronJob, ...]
    removed_media_files: tuple[Path, ...]


def cleanup_sensitive_state(
    *,
    config: TalonConfig,
    cron_store: CronJobStore,
    now: datetime | None = None,
) -> DataLifecycleReport:
    """Apply retention policy for sensitive persisted Talon state.

    Args:
        config: Talon process configuration.
        cron_store: Store for assistant-scoped cron records.
        now: Current timestamp override for deterministic tests.

    Returns:
        Cleanup summary.
    """
    current = datetime.now(UTC) if now is None else _coerce_utc(now)
    cron_days = _env_non_negative_int(
        config,
        "DEEPAGENTS_TALON_CRON_RETENTION_DAYS",
        DEFAULT_CRON_JOB_RETENTION_DAYS,
    )
    media_hours = _env_non_negative_int(
        config,
        "DEEPAGENTS_TALON_INBOUND_MEDIA_RETENTION_HOURS",
        DEFAULT_INBOUND_MEDIA_RETENTION_HOURS,
    )

    removed_cron_jobs = tuple(
        cron_store.prune_completed(retain_for=timedelta(days=cron_days), now=current),
    )
    removed_media_files = tuple(
        _delete_old_files(
            config.inbound_media_dir,
            cutoff=current - timedelta(hours=media_hours),
        ),
    )
    _remove_empty_dirs(config.inbound_media_dir)
    if removed_cron_jobs or removed_media_files:
        logger.info(
            "Talon data lifecycle cleanup removed %d cron job(s) and %d media file(s)",
            len(removed_cron_jobs),
            len(removed_media_files),
        )
    return DataLifecycleReport(
        removed_cron_jobs=removed_cron_jobs,
        removed_media_files=removed_media_files,
    )


def _delete_old_files(root: Path, *, cutoff: datetime) -> list[Path]:
    if not root.exists():
        return []

    removed: list[Path] = []
    for path in root.rglob("*"):
        if not path.is_file() and not path.is_symlink():
            continue
        try:
            modified = datetime.fromtimestamp(path.stat().st_mtime, tz=UTC)
        except OSError:
            continue
        if modified > cutoff:
            continue
        try:
            path.unlink()
        except OSError:
            logger.warning("Could not delete expired inbound media file: %s", path, exc_info=True)
        else:
            removed.append(path)
    return removed


def _remove_empty_dirs(root: Path) -> None:
    if not root.exists():
        return

    for path in sorted((item for item in root.rglob("*") if item.is_dir()), reverse=True):
        try:
            path.rmdir()
        except OSError:
            continue


def _env_non_negative_int(config: TalonConfig, key: str, default: int) -> int:
    value = config.env.get(key)
    if value is None:
        return default
    try:
        parsed = int(value)
    except ValueError as error:
        msg = f"{key} must be a non-negative integer"
        raise ValueError(msg) from error
    if parsed < 0:
        msg = f"{key} must be a non-negative integer"
        raise ValueError(msg)
    return parsed


def _coerce_utc(value: datetime) -> datetime:
    if value.tzinfo is None:
        return value.replace(tzinfo=UTC)
    return value.astimezone(UTC)

