"""Model-specific reasoning controls for `/effort`."""

from __future__ import annotations

import contextvars
from typing import Any

from deepagents_code.reasoning_effort import supported_efforts_for_model

ACTIVE_EFFORT: contextvars.ContextVar[dict[str, Any] | None] = contextvars.ContextVar(
    "talon_active_effort", default=None
)

# Qwen's OpenAI-compatible API accepts a token budget rather than effort labels.
# https://www.alibabacloud.com/help/en/model-studio/deep-thinking
QWEN_BUDGETS = {"low": 1024, "medium": 4096, "high": 8192, "xhigh": 16384, "max": None}

# Provider profiles can omit effort metadata even for reasoning-capable models.
# https://developers.openai.com/api/docs/models/gpt-5.6
# https://developers.openai.com/api/docs/models/gpt-6.1-sol
# https://docs.baseten.co/development/model-apis/reasoning
_FULL_EFFORTS = ("none", "low", "medium", "high", "xhigh", "max")
_DOCUMENTED_EFFORTS = {
    **dict.fromkeys(
        (
            "openai:gpt-5.6",
            "openai:gpt-5.6-luna",
            "openai:gpt-5.6-sol",
            "openai:gpt-5.6-terra",
            "openai:gpt-6-luna",
            "openai:gpt-6-sol",
        ),
        _FULL_EFFORTS,
    ),
    **dict.fromkeys(("openai:gpt-6-astra", "openai:gpt-6.1-sol"), _FULL_EFFORTS[1:]),
    **dict.fromkeys(
        (
            "baseten:zai-org/glm-5.2",
            "baseten:zai-org/glm-5.2-fast",
            "baseten:zai-org/glm-5.3",
            "baseten:zai-org/glm-5.3-fast",
            "baseten:zai-org/glm-5.3-flash",
            "baseten:deepseek-ai/deepseek-v4-pro",
            "baseten:deepseek-ai/deepseek-v4-pro-0813",
            "baseten:deepseek-ai/deepseek-v4.1-flash",
            "baseten:deepseek-ai/deepseek-v4.1-flash-fast",
        ),
        ("none", "low", "high", "max"),
    ),
    "baseten:deepseek-ai/deepseek-v4-flash-0731": (
        "none",
        "minimal",
        "low",
        "medium",
        "high",
        "xhigh",
        "max",
    ),
}


def _native_spec(spec: str) -> str:
    provider, _, name = spec.partition(":")
    namespace, _, model = name.partition("/")
    if provider == "openai" and namespace in {"openai", "anthropic", "baseten"}:
        return f"{namespace}:{model}"
    return spec


def _family(spec: str) -> str:
    provider, _, name = spec.lower().partition(":")
    name = name.rsplit("/", 1)[-1]
    if provider in {"deepseek", "openai"} and name in {
        "deepseek-flash",
        "deepseek-v4-pro",
        "deepseek-v4-flash",
        "deepseek-v4-flash-vision-exp",
    }:
        return "deepseek"
    if provider == "openai":
        if name.startswith(("qwen3", "qwen-plus", "qwen-flash")):
            if any(part in name for part in ("instruct", "coder", "omni")):
                return ""
            return "qwen"
        if name.startswith(("glm-4.5", "glm-4.6", "glm-4.7", "glm-5")):
            return "glm"
    return ""


def effort_levels(spec: str) -> tuple[str, ...]:
    """Return only reasoning controls supported by the selected model.

    Args:
        spec: Selected `provider:model` identifier.

    Returns:
        Native effort labels, Qwen budget presets, or GLM thinking modes.
    """
    spec = _native_spec(spec)
    family = _family(spec)
    if family == "deepseek":
        return ("none", "low", "high", "max")
    if family == "qwen":
        return tuple(QWEN_BUDGETS)
    if family == "glm":
        # GLM-5.3 uses forced thinking; earlier GLM models allow toggling it.
        # https://docs.z.ai/guides/capabilities/thinking-mode
        return ("on",) if "glm-5.3" in spec.lower() else ("off", "on")
    provider, _, name = spec.partition(":")
    if provider == "openai" and "/" in name:
        return ()
    return supported_efforts_for_model(spec) or _DOCUMENTED_EFFORTS.get(spec.lower(), ())


def effort_settings(spec: str, effort: str) -> dict[str, Any]:
    """Translate an allowlisted control into model invocation parameters.

    Args:
        spec: Selected `provider:model` identifier.
        effort: A supported effort label.

    Returns:
        Provider-specific invocation settings.

    Raises:
        ValueError: When the model does not support the requested control.
    """
    if effort not in effort_levels(spec):
        msg = "Unsupported reasoning effort for this model"
        raise ValueError(msg)
    spec = _native_spec(spec)
    family = _family(spec)
    if family == "deepseek":
        settings: dict[str, Any] = {
            "extra_body": {"thinking": {"type": "disabled" if effort == "none" else "enabled"}}
        }
        if effort != "none":
            settings["reasoning_effort"] = effort
        return settings
    if family == "qwen":
        body: dict[str, object] = {}
        if budget := QWEN_BUDGETS[effort]:
            body["thinking_budget"] = budget
        # Thinking-only checkpoints reject a switch to hybrid thinking.
        if "thinking" not in spec.lower():
            body["enable_thinking"] = True
        return {"extra_body": body}
    if family == "glm":
        return {"extra_body": {"thinking": {"type": "enabled" if effort == "on" else "disabled"}}}
    return {"reasoning_effort": effort}


def normalize_effort(argument: str) -> str:
    """Normalize an effort label, including the spelled-out extra-high alias.

    Args:
        argument: Command argument supplied by the operator.

    Returns:
        Canonical lowercase effort label.
    """
    value = " ".join(argument.lower().replace("-", " ").replace("_", " ").split())
    return "xhigh" if value in {"extra high", "x high"} else value

libs/talon/deepagents_talon/mcp_config.p:
"""Narrow, redacted access to Talon's operator-selected MCP configuration."""

from __future__ import annotations

import hashlib
import hmac
import json
import logging
import os
import re
import secrets
import stat
import tempfile
import time
from contextlib import contextmanager
from pathlib import Path
from typing import TYPE_CHECKING, cast

from langchain_core.tools import tool

from deepagents_talon.mcp_oauth import MCPOAuthConfigError, parse_oauth_config

if TYPE_CHECKING:
    from collections.abc import Callable, Generator, Mapping

    from langchain_core.tools import BaseTool

logger = logging.getLogger(__name__)

MCP_CONFIG_UPDATE_TOOL = "update_mcp_server"
# Duplicated from runtime._WORKSPACE_ENV: importing it would pull the runtime, and the
# public alias lives in channels, whose package imports every channel driver eagerly.
WORKSPACE_ENV = "DEEPAGENTS_TALON_WORKSPACE"
_REDACTED = "<redacted>"
_REFERENCE = re.compile(r"\$\{[A-Za-z_][A-Za-z0-9_]*\}")
_NAME = re.compile(r"[A-Za-z0-9_-]+")
_FIELDS = frozenset(
    {
        "transport",
        "type",
        "command",
        "args",
        "env",
        "url",
        "headers",
        "auth",
        "oauth",
        "allowedTools",
        "disabledTools",
        "skillOnly",
    }
)
_ENUMS = {
    "transport": {"stdio", "http", "sse", "streamable_http", "streamable-http"},
    "type": {"stdio", "http", "sse", "streamable_http", "streamable-http"},
    "auth": {"oauth"},
}
# Everything else in `_FIELDS` decides where a credential is sent or what runs.
_TOOL_FILTER_FIELDS = frozenset({"allowedTools", "disabledTools"})
_LOCK_TIMEOUT_SECONDS = 5.0
_LOCK_POLL_SECONDS = 0.05


class _UnsafeUpdateError(ValueError):
    """An auto-approved update would run new code while reusing stored secrets."""


def agent_workspace_root(env: Mapping[str, str] | None = None) -> Path:
    """Return the directory the agent's shell backend reaches with relative paths.

    Args:
        env: Runtime environment to read. Falls back to the process environment,
            which is what the default backend itself reads.

    Returns:
        The configured workspace root, or the current working directory, where
        `LocalShellBackend(root_dir=None)` runs agent commands.
    """
    configured = (env or {}).get(WORKSPACE_ENV) or os.environ.get(WORKSPACE_ENV)
    return Path(configured).expanduser().resolve() if configured else Path.cwd().resolve()


def warn_agent_workspace_path(path: Path, agent_root: Path | None, *, subject: str) -> Path:
    """Return `path` resolved, warning when it sits inside the agent workspace.

    This reports placement, not secrecy. Talon's default backend runs real shell
    commands with `virtual_mode=False`, so a path outside the workspace is still
    readable by absolute path; keeping it out of the workspace only removes the
    relative-path route and keeps it out of the model's working tree. Because it
    buys no protection at all, a bad placement is not worth failing a start over
    -- with no workspace configured the root is the working directory, so Talon
    launched from `$HOME` puts both default paths inside it.

    Args:
        path: Operator-selected path to check.
        agent_root: Workspace root. Falls back to `agent_workspace_root()`.
        subject: Name of the file, used in the warning.

    Returns:
        The resolved path, with the final component left unresolved.
    """
    resolved = path.parent.resolve() / path.name
    root = agent_workspace_root() if agent_root is None else agent_root
    # This stays a warning, because no filesystem deny rule can promote it to an
    # error. FilesystemMiddleware refuses to load permissions at all alongside an
    # execution-capable backend (deepagents/middleware/filesystem.py:1741-1748,
    # "Tool-level permissions for the execute tool are not implemented"), and
    # every _check_fs_permission call site in that file guards a read or write
    # tool -- none guards execute -- so even routing the paths through a
    # CompositeBackend would not stop `cat`. Keeping these files away from the
    # agent needs an OS keyring, or a directory the agent process cannot read at
    # all: a separate uid, or a sandboxed backend.
    if resolved.is_relative_to(root):
        logger.warning(
            "%s %s is inside the agent workspace %s; move it elsewhere, or point %s "
            "at a directory that does not contain it",
            subject,
            resolved,
            root,
            WORKSPACE_ENV,
        )
    return resolved


class MCPConfigStore:
    """Manage one fixed file without exposing stored credentials to tools.

    Nothing here is a confidentiality boundary. Placement is checked and warned
    about, not enforced, and against Talon's default shell backend `cat` and
    `echo >` on the absolute path bypass redaction, the revision CAS, the
    `O_NOFOLLOW` open, and the `update_mcp_server` approval interrupt alike. So
    `update_mcp_server` mediates change; it cannot keep a configured secret from
    the model. Only `${ENV_VAR}` references, which are never expanded here, do
    that, and no filesystem deny rule can change it -- see
    `warn_agent_workspace_path` for why that approach is closed off. Moving
    credentials somewhere the agent process cannot read is tracked separately.

    Args:
        path: Operator-selected configuration path, ideally outside the agent
            workspace; a path inside it is warned about, not rejected.
        on_update: Schedule a reload after a successful write.
        agent_root: Agent workspace root. Defaults to the process workspace.
        auto_approve: Optional standalone override; otherwise use the invocation policy.
    """

    def __init__(
        self,
        path: Path,
        on_update: Callable[[], None],
        *,
        agent_root: Path | None = None,
        auto_approve: bool | None = None,
    ) -> None:
        """Capture the operator path and a process-local revision key."""
        self._path = warn_agent_workspace_path(path, agent_root, subject="MCP configuration")
        self._on_update = on_update
        self._revision_key = secrets.token_bytes(32)
        self._auto_approve = auto_approve

    def tools(self) -> tuple[BaseTool, BaseTool]:
        """Return the read and single-server update capabilities."""

        @tool
        def get_mcp_configuration() -> dict[str, object]:
            """View MCP server configuration and its revision without reading files.

            Stored strings are <redacted>, except transport/auth enums and exact
            ${ENV_VAR} references. Values are never expanded. Use this revision
            with update_mcp_server. This tool and update_mcp_server are the
            supported way to read and change MCP settings; do not read or edit
            the configuration file with filesystem or shell tools.
            """
            return self._view()

        @tool
        def update_mcp_server(
            server_name: str, server: dict[str, object] | None, expected_revision: str
        ) -> dict[str, str]:
            """Add, replace, or remove one MCP server; normally requires approval.

            Args:
                server_name: Server name from mcpServers, or a new name.
                server: Complete replacement settings, or null to remove. Copy
                    <redacted> at the same field to preserve its stored value.
                    Omitted fields are removed, except settings Talon does not
                    manage, which are preserved and never shown. Use ${ENV_VAR}
                    references for credentials; never include literal secrets.
                expected_revision: Revision returned by get_mcp_configuration.

            Changes can execute commands or send credentials to configured URLs.
            Saved changes activate only after a successful reload before the next turn.
            Use get_agent_tools to verify activation. Running tasks retain old capabilities.
            """
            return self._update(server_name, server, expected_revision)

        return get_mcp_configuration, update_mcp_server

    def _revision(self, raw: bytes | None) -> str:
        return hmac.new(
            self._revision_key, b"missing" if raw is None else b"file:" + raw, hashlib.sha256
        ).hexdigest()

    def _read(self) -> tuple[bytes | None, dict[str, object]]:
        _require_posix()
        try:
            descriptor = os.open(self._path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        except FileNotFoundError:
            return None, {"mcpServers": {}}
        with os.fdopen(descriptor, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                msg = "MCP configuration must be a regular file"
                raise ValueError(msg)
            raw = stream.read()
        document = json.loads(raw)
        if not isinstance(document, dict) or not isinstance(document.get("mcpServers"), dict):
            msg = "Invalid MCP configuration"
            raise TypeError(msg)
        return raw, document

    def _view(self) -> dict[str, object]:
        try:
            raw, document = self._read()
            servers = cast("dict[str, object]", document["mcpServers"])
            return {
                "revision": self._revision(raw),
                "mcpServers": {name: _redact_server(server) for name, server in servers.items()},
            }
        except OSError, ValueError, TypeError, RecursionError:
            return {"status": "error", "message": "Cannot read MCP configuration."}

    def _update(self, name: str, server: dict[str, object] | None, revision: str) -> dict[str, str]:
        try:
            if not _NAME.fullmatch(name):
                return {"status": "error", "message": "Invalid server name."}
            with locked_path(self._path):
                raw, document = self._read()
                if not hmac.compare_digest(self._revision(raw), revision):
                    return {"status": "conflict", "message": "Read the configuration again."}
                self._replace_server(document, name, server)
                _atomic_write(self._path, document)
        except TimeoutError:
            return {"status": "conflict", "message": "Configuration is busy; try again."}
        except (_UnsafeUpdateError, MCPOAuthConfigError) as exc:
            return {"status": "error", "message": str(exc)}
        except OSError, ValueError, TypeError, RecursionError:
            return {
                "status": "error",
                "message": "Cannot update MCP configuration; check settings.",
            }
        self._on_update()
        return {"status": "updated", "available": "after_successful_reload"}

    def _replace_server(
        self, document: dict[str, object], name: str, server: dict[str, object] | None
    ) -> None:
        servers = cast("dict[str, object]", document["mcpServers"])
        if server is None:
            servers.pop(name, None)
            return
        previous = servers.get(name)
        replacement = cast("dict[str, object]", _restore(server, previous))
        _validate_server(replacement)
        if self._auto_approve if self._auto_approve is not None else _unapproved_update():
            _reject_unapproved_execution_change(server, replacement, previous)
        # Settings Talon does not manage are invisible to the model, so an edit
        # must put them back rather than drop them.
        servers[name] = replacement | _unmanaged_fields(previous)


@contextmanager
def locked_path(path: Path, *, timeout: float | None = None) -> Generator[None]:
    """Hold an exclusive lock for `path` while the block runs.

    The lock is a sidecar `.lock` file beside `path`, so readers that only open
    the target are unaffected. Acquisition is non-blocking with a bounded retry:
    a stale holder surfaces as a timeout the caller can report, rather than
    wedging a tool call or a worker thread with nothing shown to anyone.

    Args:
        path: File the lock protects.
        timeout: Seconds to keep retrying before giving up. Defaults to
            `_LOCK_TIMEOUT_SECONDS`, read at call time.

    Yields:
        None, with the lock held.

    Raises:
        TimeoutError: Another holder still had the lock when `timeout` elapsed.
    """
    _require_posix()
    import fcntl  # noqa: PLC0415  # Keep Talon importable on non-POSIX hosts.

    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    descriptor = os.open(
        path.with_name(path.name + ".lock"),
        os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW,
        0o600,
    )
    with os.fdopen(descriptor, "rb") as lock:
        deadline = time.monotonic() + (_LOCK_TIMEOUT_SECONDS if timeout is None else timeout)
        while True:
            try:
                fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    msg = f"Timed out waiting for the lock on {path}"
                    raise TimeoutError(msg) from None
                time.sleep(_LOCK_POLL_SECONDS)
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


def _unapproved_update() -> bool:
    from deepagents_talon.tool_approvals import ACTIVE_APPROVALS  # noqa: PLC0415

    snapshot = ACTIVE_APPROVALS.get()
    return snapshot is None or not snapshot.approvals.get(MCP_CONFIG_UPDATE_TOOL, False)


def _unmanaged_fields(previous: object) -> dict[str, object]:
    if not isinstance(previous, dict):
        return {}
    stored = cast("dict[str, object]", previous)
    return {key: value for key, value in stored.items() if key not in _FIELDS}


def _reject_unapproved_execution_change(
    submitted: dict[str, object],
    replacement: dict[str, object],
    previous: object,
) -> None:
    """Refuse an unapproved change that redirects a secret the caller never saw.

    `_restore` fills `<redacted>` path-wise, so a caller can keep a stored
    credential while changing where it goes: swapping `command`/`args`, flipping
    the derived transport to turn a URL into a command line, or pointing `url` at
    another host so the restored `Authorization` header is sent there. With the
    approval interrupt disabled any of those reaches a real credential
    unreviewed.

    The check is deliberately not a list of dangerous fields. The first version
    enumerated `command`, `args` and the transport, and a review caught that it
    omitted `url` -- the same attack through an unlisted field. Instead every
    managed setting must be unchanged apart from the tool filters, which cannot
    redirect anything, so a field added to `_FIELDS` later is covered by default
    rather than by remembering to add it here.

    Args:
        submitted: Settings as supplied, before redacted values were restored.
        replacement: Settings after restoring them.
        previous: Stored settings for this server, if any.

    Raises:
        _UnsafeUpdateError: The update reuses a stored secret and changes a
            setting that could send it somewhere else.
    """
    if not _restores_redacted(submitted):
        return
    old = cast("dict[str, object]", previous) if isinstance(previous, dict) else {}
    if _redirecting_fields(replacement) == _redirecting_fields(old):
        return
    msg = (
        "Auto-approved MCP updates that reuse <redacted> values cannot change any "
        "other setting; only allowedTools and disabledTools may differ. Resend the "
        "settings with ${ENV_VAR} references instead of redacted values, or ask the "
        "operator to re-enable update approval."
    )
    raise _UnsafeUpdateError(msg)


def _redirecting_fields(server: dict[str, object]) -> dict[str, object]:
    return {
        key: value
        for key, value in server.items()
        if key in _FIELDS and key not in _TOOL_FILTER_FIELDS
    }


def _restores_redacted(value: object) -> bool:
    if isinstance(value, dict):
        return any(_restores_redacted(item) for item in value.values())
    if isinstance(value, list):
        return any(_restores_redacted(item) for item in value)
    return value == _REDACTED


def _derived_transport(server: dict[str, object]) -> object:
    return server.get("transport", server.get("type", "stdio" if "command" in server else "http"))


def _require_posix() -> None:
    if os.name != "posix":
        msg = "MCP configuration management requires POSIX file locking"
        raise OSError(msg)


def _redact_server(server: object) -> object:
    if not isinstance(server, dict):
        return _redact(server)
    return {
        key: value if isinstance(value, str) and value in _ENUMS.get(key, set()) else _redact(value)
        for key, value in server.items()
        if key in _FIELDS
    }


def _redact(value: object) -> object:
    if isinstance(value, dict):
        return {key: _redact(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_redact(item) for item in value]
    if isinstance(value, str):
        return value if _REFERENCE.fullmatch(value) else _REDACTED
    return value


def _restore(value: object, previous: object) -> object:
    if value == _REDACTED:
        if not isinstance(previous, str):
            msg = "No stored value for redacted field"
            raise ValueError(msg)
        return previous
    if isinstance(value, dict):
        old = previous if isinstance(previous, dict) else {}
        return {key: _restore(item, old.get(key)) for key, item in value.items()}
    if isinstance(value, list):
        old_list = previous if isinstance(previous, list) else []
        return [
            _restore(item, old_list[i] if i < len(old_list) else None)
            for i, item in enumerate(value)
        ]
    return value


def _validate_server(server: dict[str, object]) -> None:
    # Reuse pure loader validation; never resolve environment values or open sessions.
    from deepagents_talon.mcp import _filter_tools, _stdio_connection  # noqa: PLC0415

    if server.keys() - _FIELDS:
        msg = "Unsupported MCP settings"
        raise ValueError(msg)
    _validate_fields(server)
    _validate_references(server)
    if "oauth" in server:
        if server.get("auth") != "oauth" or _derived_transport(server) == "stdio":
            msg = "MCP oauth settings require a remote server with auth set to oauth."
            raise MCPOAuthConfigError(msg)
        parse_oauth_config(server["oauth"])
    transport = _derived_transport(server)
    for field, choices in _ENUMS.items():
        if field in server and server[field] not in choices:
            msg = "Invalid MCP transport or authentication"
            raise ValueError(msg)
    if transport == "stdio":
        _stdio_connection("server", server)
    else:
        _validate_remote(server)
    _filter_tools("server", server, ())


def _validate_fields(server: dict[str, object]) -> None:
    if "skillOnly" in server and not isinstance(server["skillOnly"], bool):
        msg = "MCP skillOnly must be a boolean"
        raise TypeError(msg)
    for field in ("command", "url", "auth"):
        if field in server and not isinstance(server[field], str):
            msg = "MCP settings must contain strings"
            raise TypeError(msg)
    args = server.get("args", [])
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        msg = "MCP args must contain strings"
        raise TypeError(msg)
    for field in ("env", "headers"):
        values = server.get(field, {})
        if not isinstance(values, dict) or not all(
            isinstance(key, str) and isinstance(value, str) for key, value in values.items()
        ):
            msg = "MCP environment and headers must contain strings"
            raise TypeError(msg)


def _validate_references(server: dict[str, object]) -> None:
    from deepagents_talon.mcp import _ENV_REF  # noqa: PLC0415  # Avoid a module import cycle.

    values = [server.get(field, "") for field in ("command", "url")]
    values.extend(cast("list[str]", server.get("args", [])))
    for field in ("env", "headers"):
        values.extend(cast("dict[str, str]", server.get(field, {})).values())
    if any(isinstance(value, str) and "${" in _ENV_REF.sub("", value) for value in values):
        msg = "Malformed MCP environment reference"
        raise ValueError(msg)


def _validate_remote(server: dict[str, object]) -> None:
    url = server.get("url")
    headers = cast("dict[str, str]", server.get("headers", {}))
    if not isinstance(url, str) or not url:
        msg = "Remote MCP server requires a URL"
        raise ValueError(msg)
    if server.get("auth") == "oauth" and any(key.lower() == "authorization" for key in headers):
        msg = "OAuth cannot be combined with an Authorization header"
        raise ValueError(msg)


def _atomic_write(path: Path, document: dict[str, object]) -> None:
    descriptor, temporary = tempfile.mkstemp(prefix=".mcp-", dir=path.parent)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            json.dump(document, stream, indent=2, allow_nan=False)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        if path.is_symlink():
            msg = "MCP configuration must not be a symlink"
            raise ValueError(msg)
        Path(temporary).replace(path)
    finally:
        Path(temporary).unlink(missing_ok=True)

libs/talon/deepagents_talon/mcp_middlewa:
"""Talon middleware for MCP tool invocation."""

from __future__ import annotations

from typing import TYPE_CHECKING

from langchain.agents.middleware import wrap_tool_call
from langchain_core.messages import ToolMessage
from mcp.shared.exceptions import MCPError

from deepagents_talon.mcp import _normalize_mcp_arguments, _run_authorized

if TYPE_CHECKING:
    from collections.abc import Awaitable, Callable

    from langchain.agents.middleware.types import AgentMiddleware, ToolCallRequest

MCP_TOOL_METADATA_KEY = "_deepagents_talon_mcp"
MCP_SKILL_ONLY_METADATA_KEY = "_deepagents_talon_skill_only"


def talon_mcp_middleware() -> AgentMiddleware:
    """Bind Talon authorization state to metadata-marked MCP tool calls."""

    @wrap_tool_call(name="TalonMCPMiddleware")
    async def _wrap(
        request: ToolCallRequest,
        handler: Callable[[ToolCallRequest], Awaitable[ToolMessage]],
    ) -> ToolMessage:
        tool = request.tool
        if tool is None or not (tool.metadata or {}).get(MCP_TOOL_METADATA_KEY):
            return await handler(request)

        arguments = _normalize_mcp_arguments(
            request.tool_call.get("args") or {},
            tool.args_schema,
        )
        request = request.override(tool_call={**request.tool_call, "args": arguments})
        try:
            return await _run_authorized(
                request.tool_call["id"],
                lambda: handler(request),
            )
        except MCPError as exc:
            return ToolMessage(
                content=f"MCP protocol error {exc.code}: {exc.message}",
                name=request.tool_call["name"],
                tool_call_id=request.tool_call["id"],
                status="error",
            )

    return _wrap


__all__ = ["MCP_TOOL_METADATA_KEY", "talon_mcp_middleware"]

libs/talon/deepagents_talon/mcp_oauth.py:
"""Validated public-client OAuth settings for MCP servers."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from typing import cast
from urllib.parse import urlparse

from pydantic import AnyUrl

_ASCII_CONTROL_LIMIT = 32
_ASCII_DELETE = 127
_MAX_PORT = 65535


class MCPOAuthConfigError(ValueError):
    """OAuth settings are invalid, with a credential-safe diagnostic."""


@dataclass(frozen=True)
class MCPOAuthConfig:
    """Explicit public-client settings, independent of stored registration."""

    client_id: str | None = None
    callback_url: str | None = None
    scopes: tuple[str, ...] | None = None

    def storage_identity(self) -> str:
        """Return the configuration identity used to isolate credentials."""
        return json.dumps([self.client_id, self.callback_url, self.scopes])


def parse_oauth_config(value: object) -> MCPOAuthConfig:
    """Validate optional public-client settings without reflecting input values."""
    if value is None:
        return MCPOAuthConfig()
    if not isinstance(value, dict):
        msg = "MCP oauth must be an object."
        raise MCPOAuthConfigError(msg)
    if value.keys() - {"client_id", "callback_url", "scopes"}:
        msg = "Supported MCP oauth fields: client_id, callback_url, scopes; no secret is required."
        raise MCPOAuthConfigError(msg)
    client_id = value.get("client_id")
    if "client_id" in value and (
        not isinstance(client_id, str) or not client_id.strip() or _has_controls(client_id)
    ):
        msg = "MCP oauth.client_id must be a non-empty string without control characters."
        raise MCPOAuthConfigError(msg)
    scopes = _scopes(value)
    if scopes is not None and client_id is None:
        msg = (
            "MCP oauth.scopes requires an explicit client_id; omit scopes for dynamic registration."
        )
        raise MCPOAuthConfigError(msg)
    return MCPOAuthConfig(
        client_id=cast("str | None", client_id),
        callback_url=_callback_url(value),
        scopes=scopes,
    )


def _has_controls(value: str) -> bool:
    return any(
        ord(character) < _ASCII_CONTROL_LIMIT or ord(character) == _ASCII_DELETE
        for character in value
    )


def _callback_url(value: dict[str, object]) -> str | None:
    if "callback_url" not in value:
        return None
    url = value.get("callback_url")
    msg = (
        "MCP oauth.callback_url must be an HTTP loopback URL with an explicit port and path, "
        "without credentials, query, or fragment."
    )
    if not isinstance(url, str) or _has_controls(url) or any(c.isspace() for c in url):
        raise MCPOAuthConfigError(msg)
    try:
        parsed = urlparse(url)
        valid = (
            parsed.scheme == "http"
            and parsed.hostname in {"localhost", "127.0.0.1", "::1"}
            and parsed.port is not None
            and 1 <= parsed.port <= _MAX_PORT
            and parsed.username is None
            and parsed.password is None
            and parsed.path.startswith("/")
            and not parsed.params
            and "?" not in url
            and "#" not in url
        )
    except ValueError:
        raise MCPOAuthConfigError(msg) from None
    if not valid:
        raise MCPOAuthConfigError(msg)
    try:
        canonical = str(AnyUrl(url))
    except ValueError:
        raise MCPOAuthConfigError(msg) from None
    if canonical != url:
        msg = (
            "MCP oauth callback URL must use canonical spelling and a non-default port; "
            "register that exact URL with the server."
        )
        raise MCPOAuthConfigError(msg)
    return url


def _scopes(value: dict[str, object]) -> tuple[str, ...] | None:
    if "scopes" not in value:
        return None
    scopes = value["scopes"]
    if not isinstance(scopes, list) or not all(
        isinstance(scope, str) and re.fullmatch(r"[\x21\x23-\x5b\x5d-\x7e]+", scope)
        for scope in scopes
    ):
        msg = "MCP oauth.scopes must be a list of non-empty OAuth scope tokens."
        raise MCPOAuthConfigError(msg)
    return tuple(dict.fromkeys(cast("list[str]", scopes)))

libs/talon/deepagents_talon/tool_approva:
"""Persist exact-name approval policies separately from invocation snapshots."""

from __future__ import annotations

import hashlib
import json
import os
import stat
import tempfile
import unicodedata
from collections.abc import Mapping
from contextlib import suppress
from contextvars import ContextVar
from dataclasses import dataclass
from pathlib import Path
from types import MappingProxyType
from typing import TYPE_CHECKING

from langchain_core.tools import tool

from deepagents_talon.mcp_config import locked_path

if TYPE_CHECKING:
    from langchain.agents.middleware import InterruptOnConfig
    from langchain_core.tools import BaseTool

_MAX_BYTES = 1_048_576
_MAX_TOOLS = 4096
_MAX_NAME = 256
_DEFAULTS = dict.fromkeys(
    (
        "update_tool_approvals",
        "delete_conversations",
        "update_mcp_server",
        "start_async_task",
        "send_message",
    ),
    True,
)


def _validate(document: object) -> dict[str, bool]:
    if not isinstance(document, Mapping) or len(document) > _MAX_TOOLS:
        msg = "Invalid tool approvals mapping."
        raise ValueError(msg)
    result = {}
    for name, value in document.items():
        if (
            not isinstance(name, str)
            or not 0 < len(name) <= _MAX_NAME
            or name != name.strip()
            or any(c in "*?[]" or unicodedata.category(c).startswith("C") for c in name)
            or type(value) is not bool
        ):
            msg = "Invalid tool approval entry."
            raise ValueError(msg)
        result[name] = value
    return result


def _unique_entries(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for name, value in pairs:
        if name in result:
            msg = "Duplicate tool approval entry."
            raise ValueError(msg)
        result[name] = value
    return result


@dataclass(frozen=True)
class ApprovalSnapshot:
    """Immutable byte revision and exact-name policy; unspecified tools need no prompt."""

    revision: str
    approvals: Mapping[str, bool]

    def __post_init__(self) -> None:
        """Copy and freeze validated policy entries."""
        object.__setattr__(self, "approvals", MappingProxyType(_validate(self.approvals)))

    @property
    def interrupt_on(self) -> dict[str, bool | InterruptOnConfig]:
        """Return fresh approve/reject interrupts for enabled exact names."""
        return {
            name: {"allowed_decisions": ["approve", "reject"]}
            for name, enabled in self.approvals.items()
            if enabled
        }


ACTIVE_APPROVALS: ContextVar[ApprovalSnapshot | None] = ContextVar("ACTIVE_APPROVALS", default=None)
APPROVAL_OPERATOR: ContextVar[bool] = ContextVar("APPROVAL_OPERATOR", default=False)


class ToolApprovalStore:
    """Manage one operator-selected policy file with byte-revision compare-and-swap."""

    def __init__(self, path: Path) -> None:
        """Fix the parent directory without following the final path component."""
        self._path = path.parent.resolve() / path.name

    def ensure(self) -> ApprovalSnapshot:
        """Materialize defaults only when missing; fail on invalid existing policy."""
        with locked_path(self._path):
            try:
                return self.read()
            except FileNotFoundError:
                with suppress(FileExistsError):
                    self._write(_DEFAULTS, create=True)
                return self.read()

    def read(self) -> ApprovalSnapshot:
        """Read a bounded regular file without following symlinks; invalid policy raises."""
        descriptor = os.open(self._path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(descriptor, "rb") as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                msg = "Tool approvals must be a regular file."
                raise ValueError(msg)
            raw = stream.read(_MAX_BYTES + 1)
        if len(raw) > _MAX_BYTES:
            msg = "Tool approvals file is too large."
            raise ValueError(msg)
        document = json.loads(raw, object_pairs_hook=_unique_entries)
        return ApprovalSnapshot(hashlib.sha256(raw).hexdigest(), _validate(document))

    def _write(self, approvals: Mapping[str, bool], *, create: bool = False) -> None:
        raw = (json.dumps(dict(approvals), indent=2, sort_keys=True) + "\n").encode()
        if len(raw) > _MAX_BYTES:
            msg = "Tool approvals file is too large."
            raise ValueError(msg)
        descriptor, temporary = tempfile.mkstemp(prefix=".tools-", dir=self._path.parent)
        try:
            with os.fdopen(descriptor, "wb") as stream:
                stream.write(raw)
                stream.flush()
                os.fsync(stream.fileno())
            if create:
                os.link(temporary, self._path)
            else:
                if self._path.is_symlink():
                    msg = "Tool approvals must not be a symlink."
                    raise ValueError(msg)
                Path(temporary).replace(self._path)
        finally:
            Path(temporary).unlink(missing_ok=True)

    def update(self, updates: dict[str, object], expected_revision: str) -> dict[str, object]:
        """Atomically merge a validated batch only when the persisted byte revision matches."""
        try:
            validated = _validate(updates)
            with locked_path(self._path):
                previous = self.read()
                if previous.revision != expected_revision:
                    return {"status": "conflict", "message": "Read tool approvals again."}
                merged = _validate(dict(previous.approvals) | validated)
                if merged != previous.approvals:
                    self._write(merged)
                saved = self.read()
        except TimeoutError:
            return {"status": "conflict", "message": "Tool approvals are busy; try again."}
        except OSError, ValueError, TypeError, RecursionError:
            return {"status": "error", "message": "Cannot update tool approvals."}
        return {
            "status": "updated",
            "persisted_revision": saved.revision,
            "tools": dict(saved.approvals),
            "available": "next_invocation",
        }

    def view(self, active: ApprovalSnapshot) -> dict[str, object]:
        """Show persisted policy separately from the unchanged invocation snapshot."""
        result: dict[str, object] = {
            "active_revision": active.revision,
            "active_tools": dict(active.approvals),
        }
        try:
            saved = self.read()
        except OSError, ValueError, TypeError, RecursionError:
            return result | {
                "status": "error",
                "message": "Cannot read persisted tool approvals.",
                "persisted_revision": None,
                "tools": None,
                "saved_changes_inactive": None,
            }
        return result | {
            "persisted_revision": saved.revision,
            "tools": dict(saved.approvals),
            "saved_changes_inactive": saved.revision != active.revision,
        }

    def tools(self, active: ApprovalSnapshot) -> tuple[BaseTool, BaseTool]:
        """Bind read/update tools to an invocation snapshot, not future saved policy."""

        @tool
        def get_tool_approvals() -> dict[str, object]:
            """Read saved and invocation policies; saved changes apply next invocation only."""
            return self.view(active)

        @tool
        def update_tool_approvals(
            updates: dict[str, object], expected_revision: str
        ) -> dict[str, object]:
            """Save an operator-authorized batch for next invocation; old snapshots stay unchanged.

            Args:
                updates: Exact tool names mapped to booleans; false disables prompting,
                    not operator authorization. Unspecified entries are preserved.
                expected_revision: persisted_revision from get_tool_approvals, for CAS.
            """
            if APPROVAL_OPERATOR.get() is not True or ACTIVE_APPROVALS.get() is None:
                return {"status": "error", "message": "Operator authorization is required."}
            result = self.update(updates, expected_revision)
            if result.get("status") == "updated":
                return result | self.view(active)
            return result

        return get_tool_approvals, update_tool_approvals

