  assert.deepEqual(reactionEntry(reaction, "bot@c.us", ["bot@c.us"]), {
    event_type: "reaction", chat_id: "chat@g.us", user_id: "operator@lid",
    message_id: "true_chat@g.us_PROMPT", text: "\u{1f44d}",
