class ToolCallingModel(FakeMessagesListChatModel):
    def bind_tools(self, *_args: object, **_kwargs: object) -> Self:
        return self


@pytest.mark.parametrize(
    ("decision", "requires_approval", "trigger", "writes"),
    [
        ("approve", True, "channel", True),
        ("reject", True, "channel", False),
        (None, True, "channel", False),
        ("approve", True, "cron", False),
        (None, False, "channel", True),
        (None, False, "cron", True),
    ],
)
async def test_runtime_gates_real_config_writes(
    config_tools, decision, requires_approval, trigger, writes
):
    path, view, update, _ = config_tools
    arguments = {
        "server_name": "example",
        "server": {"command": "server"},
        "expected_revision": view.invoke({})["revision"],
    }
    model = ToolCallingModel(
        responses=[
            AIMessage(
                content="",
                tool_calls=[{"name": "update_mcp_server", "args": arguments, "id": "call"}],
            ),
            AIMessage(content="done"),
        ]
    )
    approvals: list[ToolApprovalRequest] = []

    async def approve(request: ToolApprovalRequest) -> ToolApprovalDecision:
        assert not path.exists()
        approvals.append(request)
        return decision

    async def reload_tools():
        return [view, update]

    store = ToolApprovalStore(path.parent.parent / "tools.json")
    snapshot = store.ensure()
    store.update({"update_mcp_server": requires_approval}, snapshot.revision)
    runtime = DeepAgentRuntime(
        model=model,
        env={},
        tools=[],
        reload_tools=reload_tools,
        backend=StateBackend(),
        approval_store=store,
        include_web_tools=False,
        skills=(),
        memory=(),
    )
    await runtime.start()
    try:
        await runtime.reload_mcp_configuration()
        await runtime.invoke(
            AgentRequest(
                conversation_id="chat",
                text="configure MCP",
                metadata={"trigger": trigger},
                approval_handler=approve if decision is not None else None,
            )
        )
    finally:
        await runtime.stop()
    assert path.exists() is writes
    assert bool(approvals) is (decision is not None and trigger != "cron")


