    revision = view.invoke({})["revision"]
    holding = threading.Event()
    release = threading.Event()

    def hold_the_lock() -> None:
        with locked_path(path):
            holding.set()
            release.wait(5.0)

    holder = threading.Thread(target=hold_the_lock)
    holder.start()
    try:
